values
  ('ai:ai-batch-03:a8d0be70f837','A1'::public.cefr_level,'reading','What is the capital city of the United Kingdom?',array['London','Cardiff','Belfast','Paris']::text[],'A','''London is the capital city of England and of the United Kingdom.''',array['life_in_uk','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','Sam lives in London. London is the capital city of England and of the United Kingdom. The River Thames goes through London. Every day Sam walks to school. He likes the red buses. On Saturdays he visits his grandmother in Cardiff, the capital city of Wales.',null,null,null,'practice'),
  ('ai:ai-batch-03:7e164ffead13','A1'::public.cefr_level,'reading','Which river goes through London?',array['the Thames','the Nile','the Severn','the Clyde']::text[],'A','''The River Thames goes through London.''',array['life_in_uk','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','Sam lives in London. London is the capital city of England and of the United Kingdom. The River Thames goes through London. Every day Sam walks to school. He likes the red buses. On Saturdays he visits his grandmother in Cardiff, the capital city of Wales.',null,null,null,'practice'),
  ('ai:ai-batch-03:028453bb741d','A1'::public.cefr_level,'reading','Where does Sam''s grandmother live?',array['in Cardiff','in Edinburgh','in Belfast','in London']::text[],'A','''He visits his grandmother in Cardiff.''',array['life_in_uk','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','Sam lives in London. London is the capital city of England and of the United Kingdom. The River Thames goes through London. Every day Sam walks to school. He likes the red buses. On Saturdays he visits his grandmother in Cardiff, the capital city of Wales.',null,null,null,'practice'),
  ('ai:ai-batch-03:0dcefc664818','A1'::public.cefr_level,'reading','What is in the centre of Edinburgh?',array['an airport','a beach','an old castle','a big lake']::text[],'C','''In the centre of the city there is a very old castle on a hill.''',array['britain','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','My name is Ella. I live in Edinburgh. Edinburgh is the capital city of Scotland. In the centre of the city there is a very old castle on a hill. On 31 December we celebrate Hogmanay, the Scottish New Year. We watch the fireworks with our family.',null,null,null,'practice'),
  ('ai:ai-batch-03:e173df605171','A1'::public.cefr_level,'reading','When does Ella celebrate Hogmanay?',array['in June','on 5 November','in March','on 31 December']::text[],'D','''On 31 December we celebrate Hogmanay, the Scottish New Year.''',array['britain','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','My name is Ella. I live in Edinburgh. Edinburgh is the capital city of Scotland. In the centre of the city there is a very old castle on a hill. On 31 December we celebrate Hogmanay, the Scottish New Year. We watch the fireworks with our family.',null,null,null,'practice'),
  ('ai:ai-batch-03:bd83623e5484','A1'::public.cefr_level,'reading','What does Ella''s family do at Hogmanay?',array['They watch the fireworks.','They go to school.','They stay in bed.','They go to the beach.']::text[],'A','''We watch the fireworks with our family.''',array['britain','story']::text[],'draft','unreviewed','ai-draft:ai-batch-03','My name is Ella. I live in Edinburgh. Edinburgh is the capital city of Scotland. In the centre of the city there is a very old castle on a hill. On 31 December we celebrate Hogmanay, the Scottish New Year. We watch the fireworks with our family.',null,null,null,'practice'),
  ('ai:ai-batch-03:3bf77ec6eccf','A1'::public.cefr_level,'reading','What does Harry want to drink?',array['tea','coffee','water','juice']::text[],'A','''A cup of tea, please.''',array['dialogue']::text[],'draft','unreviewed','ai-draft:ai-batch-03','Waiter: Hello! What would you like?
