  ('ai:ai-batch-03:707d553a17ea','A1'::public.cefr_level,'reading','Look at the flag. This is the flag of ___.',array['Wales','France','Scotland','England']::text[],'D','The flag of England is the cross of St George: a red cross on a white background.',array['britain','picture']::text[],'draft','unreviewed','ai-draft:ai-batch-03',null,'image','samples/flag_england.png','A flag','practice'),
