  ('ai:ai-batch-03:0855edc14f14','A2'::public.cefr_level,'reading','What kind of ticket does the passenger buy?',array['a monthly ticket','a return ticket','a single ticket','a bus ticket']::text[],'B','''A return ticket to Manchester.''',array['dialogue']::text[],'draft','unreviewed','ai-draft:ai-batch-03','Passenger: A return ticket to Manchester, please.
