  ('ai:ai-batch-03:5d5df3834723','B2'::public.cefr_level,'vocabulary','The Act of Union of 1707 created the Kingdom of Great Britain by uniting England and ___.',array['Wales','France','Ireland','Scotland']::text[],'D','In 1707 England (with Wales) and Scotland were united.',array['life_in_uk','history']::text[],'draft','unreviewed','ai-draft:ai-batch-03',null,null,null,null,'practice'),
